import React, { useState } from "react";
import WeatherResults from "../WeatherResults/WeatherResults";
import "./WeatherDashboard.css"; // Import the CSS file
import { UseWeather } from "../hooks/UseWeather";

function App() {
  const [input, setInput] = useState("");
  const [activeTab, setActiveTab] = useState('current'); // State for active tab
  const { results, hourlyResults, loading, error, fetchWeather } = UseWeather();

  const handleSearch = (e) => {
    e.preventDefault();
    fetchWeather(input); // Call fetchWeather with the input
  };

  const handleInputChange = (event) => {
    setInput(event.target.value);
  };

  const handleTabChange = (tab) => {
    setActiveTab(tab); // Function to change the active tab
  };

  return (
    <div className="weather-app">
      <div>
        <div className="tabs flex flex-row-reverse gap-lg">
          <div 
            className={`tab ${activeTab === 'current' ? 'active' : ''}`} 
            onClick={() => handleTabChange('current')}
          >
            Today
          </div>
          <div 
            className={`tab ${activeTab === 'future' ? 'active' : ''}`} 
            onClick={() => handleTabChange('future')}
          >
            14-Day Forecast
          </div>
        </div>
      </div>
      <div className="search-container">
        <input 
          className="border-radius-xxl"
          type="text"
          value={input}
          onChange={handleInputChange}
          placeholder="Enter city..."
        />
        <button onClick={handleSearch}>Search</button>
      </div>
      <div>
        {loading && <p>LOADING ...</p>}
        {error && <p>{error}</p>}
        {!results && !loading && !error && <p>There are no results</p>}
      </div>
      {results && (
        <div>
          {activeTab === 'current' && <WeatherResults />}
          {/* {activeTab === 'future' && <FutureWeather />} */}
        </div>
      )}
    </div>
  );
}

export default App;
